#!/usr/bin/env node
// Generated by Keel — read-only drift check: docs against the repo. Copy to .keel/check.mjs (every upgrade).
// Usage: node .keel/check.mjs [--json]     report findings; writes nothing, ever
//        node .keel/check.mjs --self-test
// Exit 0 = clean, 1 = findings. One finding per line: [kind] file:line message.
// Kinds:
//   missing-file     a file every keel project has: AGENTS.md, CLAUDE.md, .keel/meta.json, .keel/doc-size.mjs
//   dead-link        a relative Markdown link whose file, or #heading in a .md file, does not exist
//   adr-missing      an unlinked ADR index row (not Reserved) with no docs/adr/ADR-NNN-*.md file (a linked one is a dead-link)
//   adr-unindexed    an ADR file with no row in docs/adr/README.md
//   adr-status       index Status stage ≠ the file's latest Status stage, or "Superseded by" an ADR that does not exist
//   adr-header       an ADR frontmatter header (2.6+, new ADRs only) whose id ≠ the file or status ≠ the Status cell
//   rule-ref         a .claude/rules/*.md with no paths: frontmatter, or citing an ADR/NFR ID that does not exist
//   phase-gates-open a ✅ phase whose exit-gate table still has a ⬜ or 🔄 row
//   phase-path       a path cited by a ✅ phase (Evidence, ✅ gate artefact, [x] deliverable) or a non-✅
//                    phase's Workflow script that does not exist
//   missing-type     (2.6.1+ projects) a catalog document type with neither a file nor a stub (see TYPES)
//   stub-triggered   a stub (<!-- keel:stub trigger=… -->) whose trigger the repo now shows: write the full document
//   rules-missing    an ADR whose header names paths, cited by no .claude/rules/*.md
//   stack-undocumented  a runtime dependency (package.json dependencies, requirements.txt, go.mod, Cargo.toml)
//                    named in no record doc (ARCHITECTURE, HLD, LLD, ENGINEERING_DESIGN, NFR, ADRs, AGENTS.md)
// Scanned: .claude/rules/**.md, AGENTS.md, CLAUDE.md, root CHANGELOG/COMMANDS/RUNBOOK.md, docs/**.md. Archives (ARCHIVE in the
// name, LEGACY_*, archive/ folders) are history: never scanned, only link targets. Fenced code, inline code
// and HTML comments are skipped, as is anything holding {{.
import { readdirSync, readFileSync, existsSync, statSync, writeFileSync, mkdirSync, mkdtempSync } from 'fs'
import { join, posix } from 'path'
import { tmpdir } from 'os'

const { dirname, basename, normalize } = posix
const ROOT_DOCS = ['AGENTS.md', 'CLAUDE.md', 'CHANGELOG.md', 'COMMANDS.md', 'RUNBOOK.md']
const REQUIRED = ['AGENTS.md', 'CLAUDE.md', '.keel/meta.json', '.keel/doc-size.mjs']
const RECORD = /(^|\/)(ARCHITECTURE|HLD|LLD|ENGINEERING_DESIGN|NFR)\.md$|(^|\/)adr\/|^AGENTS\.md$|^docs\/(architecture|hld|lld|engineering-design|nfr)\//i
// Every catalog document type (2.6.1): [label, accepted paths, stub trigger]. A type that does not apply yet
// is a stub file, never an omission. On-demand types (SPIKE, AUDIT, PHASE_ARCHIVE, COST_ANALYSIS) are not here.
const TYPES = [
  ['BRD', ['docs/BRD.md']], ['ARCHITECTURE', ['docs/ARCHITECTURE.md']], ['IMPLEMENTATION_PLAN', ['docs/IMPLEMENTATION_PLAN.md']],
  ['CHANGELOG', ['CHANGELOG.md']], ['transcript', ['docs/keel-transcript.md']], ['docs index', ['docs/README.md']],
  ['ADR index', ['docs/adr/README.md']],
  ['PRD', ['docs/PRD.md'], 'users'], ['ENGINEERING_DESIGN', ['docs/ENGINEERING_DESIGN.md'], 'nontrivial'],
  ['HLD', ['docs/HLD.md'], 'multi-component'], ['LLD', ['docs/LLD.md'], 'mvp'], ['NFR', ['docs/NFR.md'], 'mvp'],
  ['DESIGN', ['docs/DESIGN.md', 'DESIGN.md'], 'ui'], ['COMMANDS', ['docs/COMMANDS.md', 'COMMANDS.md'], 'runs'],
  ['DEPLOYMENT', ['docs/DEPLOYMENT.md'], 'deployed'], ['RUNBOOK', ['docs/RUNBOOK.md', 'RUNBOOK.md'], 'deployed'],
  ['FEEDBACK_ROUNDS', ['docs/FEEDBACK_ROUNDS.md'], 'external-reviewers'], ['COMPLIANCE', ['docs/COMPLIANCE.md'], 'pii'],
  ['THREAT_MODEL', ['docs/THREAT_MODEL.md'], 'high-risk'], ['extension contract spec', [/^docs\/[A-Z_]+_SPEC\.md$/], 'extensible'],
  ['almanac', ['almanac/README.md'], 'product-dimension'],
]
const STUB = /<!--\s*keel:stub\s+trigger=([\w-]+)\s*-->/
const isArchive = f => /ARCHIVE/i.test(basename(f)) || /^LEGACY_/i.test(basename(f)) || /(^|\/)archive\//i.test(f)
const ADR_FILE = /^docs\/adr\/(ADR-(\d+))[^/]*\.md$/i
const STAGES = ['reserved', 'proposed', 'accepted', 'built', 'superseded']
// A Status cell is "Proposed … · Accepted … · Built `abc` …" (or "→" between steps): its stage is the last " · " segment that
// starts with a stage word (so "Accepted (implemented). Built via …" stays accepted).
const stage = s => s.split(/\s[·→]\s/).reduce((best, seg) => {
  const i = STAGES.findIndex(st => new RegExp(`^\\W*${st}\\b`, 'i').test(seg.trim()))
  return i >= 0 ? i : best
}, -1)

// Blank out code fences, inline code and HTML comments, keeping line numbers.
const blank = s => s.replace(/[^\n]/g, ' ')
const prose = t => t.replace(/```[\s\S]*?```|~~~[\s\S]*?~~~|<!--[\s\S]*?-->/g, blank).replace(/`[^`\n]*`/g, blank)
// YAML frontmatter only at the very start of the file (a later --- is a rule, not a header).
const front = t => t.match(/^---\r?\n([\s\S]*?)\r?\n---[ \t]*(?:\r?\n|$)/)?.[1]
const lineOf = (text, i) => text.slice(0, i).split('\n').length
export const slug = h => h.trim().toLowerCase().replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/`/g, '')
  .replace(/[^\p{L}\p{N}\s_-]/gu, '').replace(/ /g, '-')
function anchors(text) {
  const out = new Set(), seen = {}
  for (const [, h] of text.replace(/```[\s\S]*?```|~~~[\s\S]*?~~~|<!--[\s\S]*?-->/g, blank).matchAll(/^#{1,6}\s+(.+?)\s*#*\s*$/gm)) {
    const s = slug(h), n = seen[s] = (seen[s] ?? -1) + 1
    out.add(n ? `${s}-${n}` : s)
  }
  for (const [, id] of text.matchAll(/\b(?:id|name)="([^"]+)"/g)) out.add(id)
  return out
}

// Every file (not .git, node_modules); used for document types and trigger signals.
function walkAll(root, dir = '', acc = []) {
  for (const e of readdirSync(join(root, dir || '.'), { withFileTypes: true })) {
    const p = dir ? `${dir}/${e.name}` : e.name
    if (e.isDirectory() && !['.git', 'node_modules'].includes(e.name)) walkAll(root, p, acc)
    else if (e.isFile()) acc.push(p)
  }
  return acc
}

function walk(root, dir, acc = []) {
  if (!existsSync(join(root, dir))) return acc
  for (const e of readdirSync(join(root, dir), { withFileTypes: true })) {
    const p = dir ? `${dir}/${e.name}` : e.name
    if (e.isDirectory() && e.name !== 'node_modules' && !e.name.startsWith('.')) walk(root, p, acc)
    else if (e.isFile() && e.name.endsWith('.md')) acc.push(p)
  }
  return acc
}

export function check(root) {
  const findings = [], add = (kind, file, line, msg) => findings.push({ kind, file, line, msg })
  const read = f => readFileSync(join(root, f), 'utf8')
  const exists = f => existsSync(join(root, f))
  const docs = [...ROOT_DOCS.filter(exists), ...walk(root, 'docs')].filter(f => !isArchive(f))
  const texts = new Map(docs.map(f => [f, read(f)]))
  const anchorCache = new Map()
  const anchorsOf = f => anchorCache.get(f) ?? anchorCache.set(f, anchors(read(f))).get(f)
  let links = 0

  for (const f of REQUIRED) if (!exists(f)) add('missing-file', f, 0, 'expected in every keel project')

  // Dead links.
  for (const [f, text] of texts) {
    for (const m of prose(text).matchAll(/\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g)) {
      const target = m[1]
      if (/^[a-z][\w+.-]*:/i.test(target) || target.includes('{{')) continue
      links++
      const [path, hash] = target.split('#')
      const file = !path ? f : normalize(path.startsWith('/') ? path.slice(1) : join(dirname(f), decodeURIComponent(path)))
      const line = lineOf(text, m.index)
      if (file.startsWith('..') || !exists(file)) { add('dead-link', f, line, `${target}: no such file${ADR_FILE.test(f) ? ' (the ADR is immutable: restore the target or leave a redirect stub)' : ''}`); continue }
      if (hash && file.endsWith('.md') && !statSync(join(root, file)).isDirectory() && !anchorsOf(file).has(decodeURIComponent(hash).toLowerCase()) && !anchorsOf(file).has(hash))
        add('dead-link', f, line, `${target}: no heading #${hash} in ${file}${ADR_FILE.test(f) ? ' (the ADR is immutable: restore the heading or an anchor in the target)' : ''}`)
    }
  }

  // ADRs: index vs files.
  const adrFiles = new Map() // ADR-NNN → file
  for (const f of docs) { const m = f.match(ADR_FILE); if (m) adrFiles.set(m[1].toUpperCase().replace(/-0*(\d)/, (_, d) => `-${d}`), f) }
  const norm = id => id.toUpperCase().replace(/-0*(\d)/, (_, d) => `-${d}`)
  const index = 'docs/adr/README.md', indexed = new Set()
  if (texts.has(index)) {
    const text = texts.get(index)
    const rows = [...prose(text).matchAll(/^\|[^\n]*$/gm)]
    for (const r of rows) {
      const cells = text.slice(r.index, r.index + r[0].length).split('|').slice(1, -1).map(c => c.trim())
      const id = cells[0]?.match(/ADR-\d+/i)?.[0]
      if (!id || cells.length < 3 || /^OD-/.test(cells[0])) continue
      const key = norm(id), line = lineOf(text, r.index), status = cells[2]
      indexed.add(key)
      const file = adrFiles.get(key)
      if (!file) { if (!/reserved/i.test(cells.join(' ')) && !cells[0].includes('](')) add('adr-missing', index, line, `${id} is indexed but has no file in docs/adr/`); continue }
      const fileStatus = read(file).match(/^\|\s*\*\*Status\*\*\s*\|([^\n]*)\|/m)?.[1] ?? ''
      const a = stage(status), b = stage(fileStatus)
      if (a >= 0 && b >= 0 && a !== b) add('adr-status', index, line, `${id}: index says ${STAGES[a]}, ${file} says ${STAGES[b]}`)
    }
    for (const [key, file] of adrFiles) if (!indexed.has(key)) add('adr-unindexed', file, 1, `no row in ${index}`)
  }
  for (const [f, text] of texts) {
    if (!f.startsWith('docs/adr/')) continue
    for (const m of prose(text).matchAll(/superseded by\s+\[?(ADR-\d+)/gi))
      if (!adrFiles.has(norm(m[1])) && !indexed.has(norm(m[1]))) add('adr-status', f, lineOf(text, m.index), `superseded by ${m[1]}, which does not exist`)
  }

  // ADR header (2.6+, new ADRs only; older ADRs have none and are never given one).
  const cellOf = text => text.match(/^\|\s*\*\*Status\*\*\s*\|([^\n]*)\|/m)?.[1] ?? ''
  for (const [key, file] of adrFiles) {
    const text = read(file), fm = front(text)
    if (!fm) continue
    const id = fm.match(/^id:\s*(\S+)/m)?.[1]
    if (id && norm(id) !== key) add('adr-header', file, 2, `header id ${id} ≠ ${key} (the file name)`)
    const a = stage(fm.match(/^status:\s*(.*)$/m)?.[1] ?? ''), b = stage(cellOf(text))
    if (a >= 0 && b >= 0 && a !== b) add('adr-header', file, 3, `header status ${STAGES[a]} ≠ Status cell ${STAGES[b]}`)
  }

  // Area rules: path-scoped, pointing at IDs that exist (the rule never copies the record).
  const nfrText = docs.filter(f => /(^|\/)nfr(\.md$|\/)/i.test(f)).map(f => texts.get(f)).join('\n')
  const legacyAdr = texts.get('docs/ADR.md') ?? ''
  const rules = walk(root, '.claude/rules')
  for (const f of rules) {
    const text = read(f)
    if (!/^paths:/m.test(front(text) ?? '')) add('rule-ref', f, 1, 'no paths: frontmatter, so it loads in every session')
    for (const m of prose(text).matchAll(/\b(ADR-\d+|NFR-[A-Z]+-\d+)\b/g)) {
      const id = m[1], known = id.startsWith('ADR') ? adrFiles.has(norm(id)) || new RegExp(`\\b${id}\\b`).test(legacyAdr) : new RegExp(`\\b${id}\\b`).test(nfrText)
      if (!known) add('rule-ref', f, lineOf(text, m.index), `${id} does not exist`)
    }
  }

  // Plan: phase status vs phase blocks and the paths they cite.
  const planFiles = docs.filter(f => f === 'docs/IMPLEMENTATION_PLAN.md' || f.startsWith('docs/implementation-plan/'))
  const status = new Map(), built = new Set(), blocks = []
  for (const f of planFiles) {
    const text = texts.get(f), p = prose(text)
    for (const r of p.matchAll(/^\|\s*([\d.]+)\s*(?:—|-|–)[^|]*\|\s*(✅|🔄|⬜)[^\n]*/gm)) { status.set(r[1], r[2]); if (r[2] === '✅' || /\b(merged|deployed|live)\b|\bon `[^`]+`/i.test(text.slice(r.index, r.index + r[0].length))) built.add(r[1]) }
    const heads = [...p.matchAll(/^## Phase ([\d.]+)\b.*$/gm)]
    heads.forEach((h, i) => {
      const end = i + 1 < heads.length ? heads[i + 1].index : (p.slice(h.index + 1).search(/^## /m) + h.index + 1 || text.length)
      blocks.push({ n: h[1], file: f, start: h.index, text: text.slice(h.index, end > h.index ? end : text.length) })
    })
  }
  const pathTokens = s => [...s.matchAll(/`([^`\s]+)`/g)].map(m => ({ i: m.index, p: m[1].replace(/:\d+(:\d+)?$/, '') }))
    .filter(({ p }) => p.includes('/') && !/[{*<>]|^https?:|^-/.test(p) && !/\s/.test(p))
  for (const b of blocks) {
    const st = status.get(b.n)
    if (!st || /PHASE_ARCHIVE/i.test(b.text)) continue
    const at = i => lineOf(texts.get(b.file), b.start + i)
    const missing = (p, i, why) => { if (!exists(p.replace(/^\.\//, '').replace(/\/$/, ''))) add('phase-path', b.file, at(i), `Phase ${b.n} (${st}) ${why} \`${p}\` does not exist`) }
    if (st !== '✅') {
      const w = b.text.match(/\*\*Workflow:\*\*\s*`([^`]+)`/)
      if (w && !w[1].includes('{{')) missing(w[1], w.index, 'workflow')
      continue
    }
    const gateRows = [...b.text.matchAll(/^\|(?!\s*-)(?!\s*Gate\s*\|)[^\n]*\|\s*(✅|⬜|🔄|❌)[^|\n]*\|\s*$/gm)]
    const open = gateRows.filter(r => r[1] !== '✅')
    if (open.length) add('phase-gates-open', b.file, at(open[0].index), `Phase ${b.n} is ✅ but ${open.length} exit gate(s) are not`)
    for (const r of gateRows.filter(r => r[1] === '✅')) for (const t of pathTokens(r[0])) missing(t.p, r.index + t.i, 'gate artefact')
    for (const d of b.text.matchAll(/^\s*- \[x\][^\n]*$/gim)) for (const t of pathTokens(d[0])) missing(t.p, d.index + t.i, 'deliverable')
    const e = b.text.match(/\*\*Evidence:\*\*\s*`([^`]+)`/)
    if (e && !e[1].includes('{{')) missing(e[1], e.index, 'evidence')
  }

  // ADR status vs the plan (2.6.2): "not built" text, or Accepted never moved to Built, after the phases it names are ✅.
  const phasesIn = s => [...s.matchAll(/\bPhases?\s+(\d+(?:\.\d+)?)(?:\s*(?:[–—-]|\/|,|and|&)\s*(\d+(?:\.\d+)?))?/gi)].flatMap(([, a, b]) =>
    !b ? [a] : Number.isInteger(+a) && Number.isInteger(+b) && +b > +a && +b - +a < 10 ? Array.from({ length: +b - +a + 1 }, (_, i) => String(+a + i)) : [a, b])
  const allDone = ps => ps.length > 0 && ps.every(n => built.has(n)) // built = ✅, or its row says merged/deployed/live or "on `<branch>`" (code exists)
  const notBuilt = (file, text, cell, label) => {
    for (const seg of cell.split(/[;·|]|\.\s/)) if (/\bnot (?:yet )?built\b|\bunbuilt\b/i.test(seg)) {
      const ps = phasesIn(seg), hit = ps.length ? ps.filter(n => built.has(n)) : allDone([...status.keys()]) ? [...status.keys()] : []
      if (hit.length) add('adr-status-stale', file, lineOf(text, Math.max(0, text.indexOf(cell))), `${label} says "${seg.trim().slice(0, 80)}" but the plan shows Phase ${hit.join(', ')} built (✅, merged or on a branch): update it to what was built`)
    }
  }
  if (status.size) {
    for (const [, file] of adrFiles) {
      const text = read(file), st = cellOf(text), dev = text.match(/^\|\s*Build deviation\s*\|([^\n]*)\|/m)?.[1] ?? ''
      if (stage(st) === STAGES.indexOf('superseded')) continue
      notBuilt(file, text, st, 'Status'); notBuilt(file, text, dev, 'Build deviation')
      const scope = phasesIn(st)
      if (stage(st) === STAGES.indexOf('accepted') && allDone(scope))
        add('adr-status-stale', file, lineOf(text, text.indexOf(st)), `Status is Accepted but the plan shows Phase ${scope.join(', ')} built (✅, merged or on a branch): mark it Built (commit) and fill the Build deviation row`)
    }
    if (texts.has(index)) for (const r of prose(texts.get(index)).matchAll(/^\|[^\n]*ADR-\d+[^\n]*$/gm)) notBuilt(index, texts.get(index), r[0], 'Index row')
  }

  // Stack: runtime dependencies no record doc names.
  const deps = []
  if (exists('package.json')) { try { deps.push(...Object.keys(JSON.parse(read('package.json')).dependencies || {}).map(d => ['package.json', d])) } catch { add('stack-undocumented', 'package.json', 0, 'not valid JSON; dependencies not checked') } }
  if (exists('requirements.txt')) for (const l of read('requirements.txt').split('\n')) { const m = l.match(/^\s*([A-Za-z0-9][\w.-]*)/); if (m) deps.push(['requirements.txt', m[1]]) }
  if (exists('go.mod')) for (const m of read('go.mod').matchAll(/^\s*(?:require\s+)?([\w.-]+\.[a-z]+\/[^\s]+)\s+v[\d.]+(?!.*\/\/ indirect)/gm)) deps.push(['go.mod', m[1]])
  if (exists('Cargo.toml')) { const sec = read('Cargo.toml').match(/^\[dependencies\]\n([\s\S]*?)(?=^\[|$(?![\s\S]))/m); if (sec) for (const m of sec[1].matchAll(/^([\w-]+)\s*=/gm)) deps.push(['Cargo.toml', m[1]]) }
  const corpus = docs.filter(f => RECORD.test(f)).map(f => texts.get(f)).join('\n').toLowerCase()
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  for (const [manifest, d] of deps) {
    if (d.startsWith('@types/')) continue
    const names = new Set([d, d.replace(/^@[^/]+\//, ''), d.split('/').pop(), d.replace(/^@/, '').split('/')[0]].map(n => n.toLowerCase()).filter(n => n.length > 1))
    if (![...names].some(n => new RegExp(`(^|[^\\w-])${esc(n)}($|[^\\w-])`).test(corpus)))
      add('stack-undocumented', manifest, 0, `dependency "${d}" is named in no record doc (ARCHITECTURE, HLD, LLD, ENGINEERING_DESIGN, NFR, ADRs, AGENTS.md)`)
  }

  // Document types (2.6.1+): every type present, in full or as a stub; a stub whose trigger the repo now shows.
  const files = walkAll(root)
  const ver = (() => { try { return JSON.parse(read('.keel/meta.json')).keelVersion ?? '' } catch { return '' } })()
  const atLeast = (v, w) => { const a = v.split('.').map(Number), b = w.split('.').map(Number); for (let i = 0; i < 3; i++) if ((a[i] || 0) !== b[i]) return (a[i] || 0) > b[i]; return true }
  const stubs = files.filter(f => f.endsWith('.md') && !isArchive(f)).map(f => [f, read(f).match(STUB)?.[1]]).filter(([, t]) => t)
  if (stubs.length || (/^\d+\.\d+\.\d+/.test(ver) && atLeast(ver, '2.6.1')))
    for (const [label, paths, trigger] of TYPES)
      if (!files.some(f => paths.some(p => typeof p === 'string' ? f === p : p.test(f))))
        add('missing-type', paths.find(p => typeof p === 'string') ?? 'docs/', 0, `no ${label} document and no stub${trigger ? ` (a stub names why it does not apply yet; trigger: ${trigger})` : ''}`)
  // Triggers with a signal in the repo; the others need judgment and are not checked.
  const code = files.filter(f => !/^(docs|almanac|\.keel|\.claude|\.github)\//.test(f) && !/(^|\/)(dist|build|coverage)\//.test(f))
  const signals = {
    deployed: files.find(f => /^(Dockerfile|fly\.toml|vercel\.json|netlify\.toml|render\.yaml|app\.yaml|Procfile|serverless\.ya?ml|wrangler\.toml)$/.test(f) || /^\.github\/workflows\/[^/]*deploy[^/]*\.ya?ml$/i.test(f)),
    ui: code.find(f => /\.(html|jsx|tsx|vue|svelte|css|scss)$/.test(f)),
    runs: files.find(f => /^(package\.json|Makefile|pyproject\.toml|go\.mod|Cargo\.toml|requirements\.txt)$/.test(f)),
    'multi-component': (() => { const m = code.filter(f => /(^|\/)(package\.json|go\.mod|Cargo\.toml|pyproject\.toml)$/.test(f)).map(dirname); return new Set(m).size > 1 ? m.join(', ') : undefined })(),
  }
  for (const [f, t] of stubs) if (signals[t]) add('stub-triggered', f, 0, `stub says "not needed yet" (trigger: ${t}) but the repo shows ${signals[t]}: write the full document`)

  // Docs under test (2.6.3+): README code examples and error tables carry a marker naming the file that tests them.
  if (exists('README.md')) {
    const text = read('README.md'), lines = text.split('\n')
    const marked = /<!--\s*keel:(example|asserts)\s+(\S+)\s*-->/
    if (marked.test(text) || (/^\d+\.\d+\.\d+/.test(ver) && atLeast(ver, '2.6.3'))) {
      const RUN = /^(js|javascript|mjs|cjs|jsx|ts|typescript|tsx|py|python|go|rb|ruby|rs|rust|java|kotlin|swift|php)$/i
      const markerAbove = i => { for (let k = i - 1; k >= Math.max(0, i - 2); k--) { const m = lines[k].match(marked); if (m) return m; if (lines[k].trim()) return null } return null }
      let fence = null
      lines.forEach((l, i) => {
        const f = l.match(/^\s*(```|~~~)\s*([\w+-]*)/)
        if (fence) { if (f && f[1] === fence) fence = null; return }
        if (f) { fence = f[1]; if (RUN.test(f[2]) && !markerAbove(i)) add('docs-untested', 'README.md', i + 1, `${f[2]} example with no <!-- keel:example examples/<file> --> above it: put it in examples/ and run it in a test`); return }
        const cells = /^\s*\|/.test(l) && /^\s*\|[\s:-]+\|/.test(lines[i + 1] ?? '') ? l.split('|').map(c => c.trim()) : null
        if (cells && cells.some(c => /\b(code|error)\b/i.test(c)) && cells.some(c => /^(when|meaning|means|cause|thrown when|raised when)\b/i.test(c)) && !markerAbove(i))
          add('docs-untested', 'README.md', i + 1, 'error table with no <!-- keel:asserts <test file> --> above it: a test should trigger each row')
      })
      for (const m of text.matchAll(new RegExp(marked.source, 'g'))) if (!exists(m[2])) add('docs-untested', 'README.md', lineOf(text, m.index), `keel:${m[1]} names ${m[2]}, which does not exist`)
    }
  }

  // An ADR that names paths needs an area rule citing it.
  const cited = new Set(rules.flatMap(f => [...read(f).matchAll(/\bADR-(\d+)\b/g)].map(m => norm(`ADR-${m[1]}`))))
  for (const [key, file] of adrFiles) {
    const fm = front(read(file)), paths = fm?.match(/^paths:\s*(.*)$/m)?.[1] ?? ''
    if (/[\w*]/.test(paths.replace(/\[\s*\]/, '')) && !/^status:\s*(superseded|reserved)/im.test(fm) && !cited.has(key))
      add('rules-missing', file, 4, `header names paths ${paths.trim()} but no .claude/rules/*.md cites ${basename(file).match(/ADR-\d+/i)[0]}`)
  }

  return { findings, scanned: { docs: docs.length, links, adrs: adrFiles.size, rules: rules.length, phases: status.size, deps: deps.length } }
}

export function report({ findings, scanned }) {
  const head = `keel check: ${findings.length ? `${findings.length} finding(s)` : 'clean'} — ${scanned.docs} docs, ${scanned.links} links, ${scanned.adrs} ADRs, ${scanned.rules} rules files, ${scanned.phases} phases, ${scanned.deps} dependencies checked (read-only; nothing written)`
  return [head, ...findings.map(f => `[${f.kind}] ${f.file}${f.line ? `:${f.line}` : ''} ${f.msg}`)].join('\n')
}

if (process.argv.includes('--self-test')) {
  const assert = (c, m) => { if (!c) { console.error(`self-test FAIL: ${m}`); process.exit(1) } }
  const mk = files => {
    const d = mkdtempSync(join(tmpdir(), 'keel-check-'))
    for (const [f, t] of Object.entries(files)) { mkdirSync(join(d, dirname(f)), { recursive: true }); writeFileSync(join(d, f), t) }
    return d
  }
  const plan = (st, gate, extra = '') => `# Plan\n\n### Phase status\n\n| Phase | Status |\n|---|---|\n| 0 — Guardrails | ${st} |\n| 1 — Core | ⬜ |\n\n## Phase 0 — Guardrails\n\n- [x] tests: \`tests/rules.test.js\`\n\n| Gate | Evidence level | Artefact | Verified by | Status |\n|---|---|---|---|---|\n| Rule suite green | \`unit\` | \`tests/rules.test.js\` | agent | ${gate} |\n\n**Workflow:** \`.claude/workflows/phase-0-guardrails.js\` · **Evidence:** \`.keel/evidence/phase-0.json\`\n${extra}\n## Phase 1 — Core\n\n**Workflow:** \`.claude/workflows/phase-1-core.js\`\n`
  const adr = st => `# ADR-001 — Store — Postgres\n\n| | |\n|---|---|\n| **Status** | ${st} |\n`
  const clean = {
    'AGENTS.md': '# App\n\nSee [the plan](docs/IMPLEMENTATION_PLAN.md#phase-0--guardrails) and [HLD](docs/HLD.md#data--pg-only). Uses express.\n',
    'CLAUDE.md': '@AGENTS.md\n', '.keel/meta.json': '{}', '.keel/doc-size.mjs': '',
    'package.json': JSON.stringify({ dependencies: { express: '4', '@prisma/client': '5' }, devDependencies: { vitest: '1' } }),
    'docs/HLD.md': '# HLD\n\n## Data — `pg` only\n\nPrisma over Postgres ([ADR-001](adr/ADR-001-store.md)). `[x](missing.md)` in code is ignored.\n\n<!-- [y](gone.md) -->\n',
    'docs/IMPLEMENTATION_PLAN.md': plan('✅', '✅'),
    'docs/adr/README.md': '# ADRs\n\n| ADR | Title | Status | Deciders | Date |\n|---|---|---|---|---|\n| [ADR-001](./ADR-001-store.md) | Store — Postgres | Built | eng | 2026-01-01 |\n| [ADR-006](./ADR-006-log.md) | Log — pino | Accepted | eng | 2026-01-06 |\n| ADR-002 | Reserved (Phase 1) — cache | Proposed | — | — |\n| [ADR-007](./ADR-007-pay.md) | Pay — ledger | Accepted | eng | 2026-01-07 |\n',
    'docs/adr/ADR-001-store.md': adr('Proposed 2026-01-01 · Accepted 2026-01-02 · Built `abc` 2026-01-09'),
    'docs/adr/ADR-006-log.md': adr('Accepted (implemented). Merged; built via 3 agents · —'),
    'docs/PHASE_ARCHIVE.md': '[dead](nowhere.md)\n',
    'tests/rules.test.js': '', '.claude/workflows/phase-0-guardrails.js': '', '.claude/workflows/phase-1-core.js': '',
    '.keel/evidence/phase-0.json': '{}',
    'docs/adr/ADR-007-pay.md': '---\nid: ADR-007\nstatus: Accepted\npaths: ["src/pay/**"]\ncheck: none\n---\n' + adr('Proposed 2026-01-06 · Accepted 2026-01-07') + '\n---\n',
    'docs/NFR.md': '# NFR\n\n| NFR-PERF-001 | p95 < 200 ms |\n',
    '.claude/rules/pay.md': '---\npaths:\n  - "src/pay/**"\n---\n\n# Pay rules\n\n- Money only via the ledger: ADR-007. Budget: NFR-PERF-001.\n',
  }
  const ok = check(mk(clean))
  assert(ok.findings.length === 0, `clean fixture has findings:\n${report(ok)}`)
  assert(ok.scanned.links === 6 && ok.scanned.adrs === 3 && ok.scanned.rules === 1 && ok.scanned.phases === 2 && ok.scanned.deps === 2, `scanned counts ${JSON.stringify(ok.scanned)}`)

  // Break each thing once; each must be reported with the right kind (a check proven to fail).
  const broken = { ...clean,
    '.keel/doc-size.mjs': undefined,
    'AGENTS.md': clean['AGENTS.md'] + 'Also [gone](docs/GONE.md) and [bad anchor](docs/HLD.md#nope).\n',
    'package.json': JSON.stringify({ dependencies: { express: '4', '@prisma/client': '5', zod: '3' } }),
    'docs/IMPLEMENTATION_PLAN.md': plan('✅', '⬜'),
    'docs/adr/README.md': clean['docs/adr/README.md'] + '| [ADR-003](./ADR-003-queue.md) | Queue — SQS | Accepted | eng | 2026-01-03 |\n| ADR-005 | Auth — OIDC | Accepted | eng | 2026-01-05 |\n',
    'docs/adr/ADR-001-store.md': adr('Proposed 2026-01-01 · Accepted 2026-01-02 · ⚠️ Superseded by ADR-009 2026-02-01'),
    'docs/adr/ADR-004-orphan.md': adr('Accepted 2026-01-04'),
    'tests/rules.test.js': undefined, '.claude/workflows/phase-1-core.js': undefined, '.keel/evidence/phase-0.json': undefined,
    'docs/adr/ADR-007-pay.md': clean['docs/adr/ADR-007-pay.md'].replace('id: ADR-007', 'id: ADR-070').replace('status: Accepted', 'status: Built'),
    '.claude/rules/pay.md': clean['.claude/rules/pay.md'].replace('NFR-PERF-001', 'NFR-PERF-009'),
    '.claude/rules/api.md': '# API rules\n\n- Validate at the edge: ADR-042.\n',
  }
  const res = check(mk(Object.fromEntries(Object.entries(broken).filter(([, v]) => v !== undefined))))
  const has = (kind, re) => res.findings.some(f => f.kind === kind && re.test(`${f.file}:${f.line} ${f.msg}`))
  const want = [
    ['missing-file', /\.keel\/doc-size\.mjs/],
    ['dead-link', /AGENTS\.md:4 docs\/GONE\.md: no such file/],
    ['dead-link', /docs\/HLD\.md#nope: no heading/],
    ['dead-link', /\.\/ADR-003-queue\.md: no such file/],
    ['adr-missing', /ADR-005 is indexed/],
    ['adr-unindexed', /ADR-004-orphan\.md/],
    ['adr-status', /ADR-001: index says built, .* says superseded/],
    ['adr-status', /superseded by ADR-009/],
    ['phase-gates-open', /Phase 0 is ✅ but 1 exit gate/],
    ['phase-path', /deliverable `tests\/rules\.test\.js`/],
    ['phase-path', /evidence `\.keel\/evidence\/phase-0\.json`/],
    ['phase-path', /Phase 1 \(⬜\) workflow/],
    ['stack-undocumented', /"zod"/],
    ['adr-header', /ADR-007-pay\.md:2 header id ADR-070/],
    ['adr-header', /ADR-007-pay\.md:3 header status built ≠ Status cell accepted/],
    ['rule-ref', /pay\.md:\d+ NFR-PERF-009 does not exist/],
    ['rule-ref', /api\.md:1 no paths:/],
    ['rule-ref', /api\.md:\d+ ADR-042 does not exist/],
  ]
  for (const [k, re] of want) assert(has(k, re), `expected [${k}] ${re}\n${report(res)}`)
  assert(res.findings.length === want.length, `expected ${want.length} findings, got ${res.findings.length}\n${report(res)}`)
  assert(!res.findings.some(f => /PHASE_ARCHIVE|missing\.md|gone\.md/.test(`${f.file} ${f.msg}`)), 'archives, code and comments must be skipped')
  // 2.6.1 document types: a full set (stubs where a type does not apply) is clean; then one of each new finding.
  const stub = t => `# X\n\n> **Not needed yet.** No remote environment.\n> **Write it when:** it deploys.\n\n<!-- keel:stub trigger=${t} -->\n`
  const typed = { ...clean, '.keel/meta.json': '{"keelVersion":"2.6.1"}' }
  for (const [, paths, trigger] of TYPES) { const p = paths.find(x => typeof x === 'string') ?? 'docs/CONNECTOR_SPEC.md'; if (!typed[p]) typed[p] = trigger ? stub(trigger) : '# Doc\n' }
  typed['docs/HLD.md'] = clean['docs/HLD.md']; typed['docs/COMMANDS.md'] = '# Commands\n' // package.json: COMMANDS applies
  const tOk = check(mk(typed))
  assert(tOk.findings.length === 0, `typed clean fixture has findings:\n${report(tOk)}`)
  const tBad = { ...typed, Dockerfile: 'FROM node\n', 'docs/THREAT_MODEL.md': undefined,
    'docs/adr/README.md': typed['docs/adr/README.md'] + '| [ADR-008](./ADR-008-io.md) | IO — fs | Accepted | eng | 2026-01-08 |\n',
    'docs/adr/ADR-008-io.md': '---\nid: ADR-008\nstatus: Accepted\npaths: ["src/io.js"]\n---\n' + adr('Accepted 2026-01-08').replace('ADR-001', 'ADR-008') }
  const tRes = check(mk(Object.fromEntries(Object.entries(tBad).filter(([, v]) => v !== undefined))))
  const tWant = [['stub-triggered', /DEPLOYMENT\.md:0 .*trigger: deployed.*Dockerfile/], ['stub-triggered', /RUNBOOK\.md:0 .*Dockerfile/],
    ['missing-type', /THREAT_MODEL/], ['rules-missing', /ADR-008-io\.md:4 .*cites ADR-008/]]
  for (const [k, re] of tWant) assert(tRes.findings.some(f => f.kind === k && re.test(`${f.file}:${f.line} ${f.msg}`)), `expected [${k}] ${re}\n${report(tRes)}`)
  assert(tRes.findings.length === tWant.length, `expected ${tWant.length} type findings, got ${tRes.findings.length}\n${report(tRes)}`)
  assert(check(mk({ ...clean, 'docs/LLD.md': '# LLD\n' })).findings.length === 0, 'a pre-2.6.1 project with no stub must not get missing-type')
  // 2.6.2 ADR status vs plan: Phase 0 is ✅, Phase 1 ⬜. Text about an unfinished phase is not stale.
  const row = (n, s) => `| [ADR-00${n}](./ADR-00${n}-x.md) | X | ${s} | eng | 2026-01-0${n} |\n`
  const dev = (s, d) => adr(s) + `\n| Consequence | |\n|---|---|\n| Build deviation | ${d} |\n`
  const sOk = { ...clean, 'docs/adr/README.md': clean['docs/adr/README.md'] + row(3, 'Accepted (Phase 1 scope)') + row(4, 'Built'),
    'docs/adr/ADR-003-x.md': adr('Accepted 2026-01-03 (Phase 1 scope)'),
    'docs/adr/ADR-004-x.md': dev('Accepted 2026-01-03 → Built `abc` 2026-01-09 (Phase 0)', 'Phase 1 methods not built yet') }
  const sRes0 = check(mk(sOk))
  assert(sRes0.findings.length === 0, `status fixture with an unfinished phase has findings:\n${report(sRes0)}`)
  const sBad = { ...sOk, 'docs/adr/README.md': clean['docs/adr/README.md'] + row(3, 'Accepted (Phase 0 scope)') + row(4, 'Built; Phase 0 parts not built'),
    'docs/adr/ADR-003-x.md': adr('Accepted 2026-01-03 (Phase 0 scope)'),
    'docs/adr/ADR-004-x.md': dev('Accepted 2026-01-03 · Built `abc` 2026-01-09 (Phase 0)', 'order methods not built (Phase 0/1); Phase 0 history not built') }
  const sRes = check(mk(sBad))
  const sWant = [['adr-status-stale', /ADR-003-x\.md:\d+ Status is Accepted but the plan shows Phase 0 built/], ['adr-status-stale', /ADR-004-x\.md:\d+ Build deviation says "Phase 0 history not built"/],
    ['adr-status-stale', /ADR-004-x\.md:\d+ Build deviation says "order methods not built \(Phase 0\/1\)".*Phase 0 built/],
    ['adr-status-stale', /README\.md:\d+ Index row says "Phase 0 parts not built"/]]
  for (const [k, re] of sWant) assert(sRes.findings.some(f => f.kind === k && re.test(`${f.file}:${f.line} ${f.msg}`)), `expected [${k}] ${re}\n${report(sRes)}`)
  assert(sRes.findings.length === sWant.length, `expected ${sWant.length} status findings, got ${sRes.findings.length}\n${report(sRes)}`)
  const merged = check(mk({ ...sOk, 'docs/IMPLEMENTATION_PLAN.md': plan('✅', '✅').replace('| 1 — Core | ⬜ |', '| 1 — Core | 🔄 2/3 gates met · on `phase-1-core` |') })).findings
  assert(merged.length === 2 && merged.every(f => f.kind === 'adr-status-stale' && /Phase 1 built/.test(f.msg)), `a merged phase counts as built:\n${merged.map(f => f.msg).join('\n')}`)
  // 2.6.3 docs under test: marked README is clean; unmarked example, unmarked error table, missing file reported.
  const readme = (a, b, c) => `# Lib\n\n${a}\n\`\`\`js\nconsole.log(add(1, 2)) // 3\n\`\`\`\n\n\`\`\`sh\nnpm test\n\`\`\`\n\n${b}\n| Code | When |\n|---|---|\n| not_found | unknown order id |\n\n${c}\n`
  const dOk = { ...clean, '.keel/meta.json': '{"keelVersion":"2.6.3"}', 'examples/add.mjs': '', 'test/errors.test.mjs': '',
    'README.md': readme('<!-- keel:example examples/add.mjs -->', '<!-- keel:asserts test/errors.test.mjs -->', '') }
  const dOkRes = check(mk(dOk)).findings.filter(f => f.kind === 'docs-untested')
  assert(dOkRes.length === 0, `marked README has docs-untested:\n${dOkRes.map(f => f.msg).join('\n')}`)
  const dBad = check(mk({ ...dOk, 'README.md': readme('', '', '<!-- keel:example examples/gone.mjs -->') })).findings.filter(f => f.kind === 'docs-untested')
  const dWant = [/README\.md:4 js example/, /README\.md:13 error table/, /keel:example names examples\/gone\.mjs/]
  for (const re of dWant) assert(dBad.some(f => re.test(`${f.file}:${f.line} ${f.msg}`)), `expected [docs-untested] ${re}\n${dBad.map(f => `${f.file}:${f.line} ${f.msg}`).join('\n')}`)
  assert(dBad.length === dWant.length, `expected ${dWant.length} docs-untested, got ${dBad.length}\n${dBad.map(f => `${f.line} ${f.msg}`).join('\n')}`)
  assert(!check(mk({ ...clean, '.keel/meta.json': '{"keelVersion":"2.6.2"}', 'README.md': readme('', '', '') })).findings.some(f => f.kind === 'docs-untested'), 'a pre-2.6.3 project with no marker must not get docs-untested')
  console.log(`keel check self-test: ok (clean fixtures clean; ${want.length + tWant.length + sWant.length + dWant.length} planted drifts each reported once)`)
  process.exit(0)
}

const res = check('.')
console.log(process.argv.includes('--json') ? JSON.stringify(res, null, 1) : report(res))
process.exit(res.findings.length ? 1 : 0)
